  "err.TOO_MANY_OPEN": "There are pending requests for this e-mail; please wait for them.", "err.NETWORK": "Couldn't reach the server; try again later or message us on Discord.",
  "err.BAD_EDITION": "Choose an edition.", "err.GENERIC": "The request couldn't be sent; try again.",
  "faq.no": "08 · Questions", "faq.title": "FAQ", "faq.lead": "Can't find your answer? Ask on Discord.",
  "faq": [
    ["How long does the code take?", "Payments are matched by hand, so about 24 hours; a little longer at weekends. If it takes more than 48 hours, message us on Discord with your request number."],
    ["Do I need to install anything else?", "No. The launcher installs and updates the program, the SDK and everything it needs."],
    ["On how many devices does the license work?", "One. The key is bound to your computer on first sign-in. If you change computers, message us with your request number and we'll move it for free."],
    ["How do updates arrive?", "The launcher checks for a new version on every start and installs it. The program only opens on the latest version."],
    ["Which games are supported?", "EA Sports FC 27. FC 25 and FC 26 squads open in Table Editor and Cross Data Hub; Converter converts FC 25, FIFA 23 and eFootball faces."],
    ["Where do the 3D models come from?", "Artificial Tool reads them live from your installed FC 27 through its asset bridge; they aren't distributed with the program."],
    ["Are my game files safe?", "A backup is made before saving and changes are only written when you save. Mod packages never touch the game files."],
    ["Can I upgrade later?", "Yes. Send the difference on Buy Me a Coffee, create a new request and add your current key to the note."],
    ["What if I find a bug?", "Use the \"Report a bug\" button in the program to send it with screenshots and videos; it comes straight to us."],
    ["Can I use it in online modes?", "No. Artificial Tool is for offline career and squad editing; play online modes with unmodified files."],
  ],
  "final.title": "Build your game", "final.lead": "#BuildYourGame — squads, kits, stadiums and faces in one place.",
